local PlanetariumMaker = {}
local PRODUCTS = {
    simple_wooden_planetarium = { name = "Preprost leseni planetarij", woodCost = 3, brassCost = 1, time = 5, cost = 80, education = 18, happiness = 2, description = "Preprost leseni planetarij za šolo." },
    brass_orrery = { name = "Medeninasti orerij", woodCost = 2, brassCost = 3, glassCost = 1, time = 8, cost = 220, education = 35, happiness = 2, prestige = 3, description = "Medeninasti orerij za trgovce." },
    silver_armillary_sphere = { name = "Srebrna armilarna sfera", woodCost = 2, brassCost = 2, silverCost = 2, glassCost = 1, time = 12, cost = 580, education = 52, happiness = 3, prestige = 8, description = "Srebrna armilarna sfera za plemiče." },
    gold_band_orrery = { name = "Zlatopasni orerij", woodCost = 3, brassCost = 2, goldCost = 2, silverCost = 1, glassCost = 1, time = 16, cost = 1300, education = 68, happiness = 4, prestige = 18, description = "Zlatopasni orerij za visoke plemiče." },
    jewel_inlaid_planetarium = { name = "Draguljarski planetarij", woodCost = 3, brassCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, glassCost = 2, time = 20, cost = 2700, education = 82, happiness = 6, prestige = 30, description = "Planetarij z dragulji za visoko plemstvo." },
    royal_grand_planetarium = { name = "Kraljevski veliki planetarij", woodCost = 4, brassCost = 3, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, glassCost = 3, time = 26, cost = 5500, education = 95, happiness = 12, prestige = 60, description = "Veliki kraljevski planetarij z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    planetarium_workshop = { name = "Planetarijska delavnica", cost = { gold = 280, wood = 140, stone = 100, brass = 6 }, upkeep = 6, qualityBonus = 5 },
    astronomical_loft = { name = "Astronomska podstrešje", cost = { gold = 950, wood = 280, stone = 280, glass = 8, brass = 8 }, upkeep = 22, qualityBonus = 18 },
    master_cosmography_atelier = { name = "Mojstrski kozmografski atelje", cost = { gold = 2600, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_planetarium_palace = { name = "Kraljevska planetarijska palača", cost = { gold = 10800, wood = 600, stone = 800, gold = 70, jewel = 16 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
PlanetariumMaker.woodStock = 16; PlanetariumMaker.brassStock = 14; PlanetariumMaker.glassStock = 10; PlanetariumMaker.silverStock = 6; PlanetariumMaker.goldStock = 6; PlanetariumMaker.jewelStock = 4; PlanetariumMaker.pearlStock = 4
PlanetariumMaker.productStock = {}; PlanetariumMaker.buildings = {}; PlanetariumMaker.maker = nil; PlanetariumMaker.activeMaking = {}; PlanetariumMaker.totalProducts = 0; PlanetariumMaker.dayTimer = 0
function PlanetariumMaker.init() PlanetariumMaker.woodStock=16; PlanetariumMaker.brassStock=14; PlanetariumMaker.glassStock=10; PlanetariumMaker.silverStock=6; PlanetariumMaker.goldStock=6; PlanetariumMaker.jewelStock=4; PlanetariumMaker.pearlStock=4; PlanetariumMaker.productStock={}; PlanetariumMaker.buildings={}; PlanetariumMaker.maker=nil; PlanetariumMaker.activeMaking={}; PlanetariumMaker.totalProducts=0; PlanetariumMaker.dayTimer=0; print("[PlanetariumMaker] Royal Planetarium Maker System initialized (6 products, 4 buildings)") end
function PlanetariumMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlanetariumMaker.maker={name=n or ("Planetarist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Planetarist najet: %s (spretnost: %d)",PlanetariumMaker.maker.name,s),"success") end; return true end
function PlanetariumMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlanetariumMaker.build(id) local ok,e=PlanetariumMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlanetariumMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlanetariumMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlanetariumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlanetariumMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PlanetariumMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and PlanetariumMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.glassCost and PlanetariumMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and PlanetariumMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlanetariumMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlanetariumMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlanetariumMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlanetariumMaker.buildings==0 then return false,"Potrebna planetarijska delavnica" end; if not PlanetariumMaker.maker then return false,"Potreben planetarist" end; return true end
function PlanetariumMaker.make(pt,qty) qty=qty or 1; local ok,e=PlanetariumMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PlanetariumMaker.woodStock=PlanetariumMaker.woodStock-d.woodCost*qty end; if d.brassCost then PlanetariumMaker.brassStock=PlanetariumMaker.brassStock-d.brassCost*qty end; if d.glassCost then PlanetariumMaker.glassStock=PlanetariumMaker.glassStock-d.glassCost*qty end; if d.silverCost then PlanetariumMaker.silverStock=PlanetariumMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlanetariumMaker.goldStock=PlanetariumMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlanetariumMaker.jewelStock=PlanetariumMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlanetariumMaker.pearlStock=PlanetariumMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlanetariumMaker.maker then t=math.max(1,t-math.floor(PlanetariumMaker.maker.skill/13)) end; table.insert(PlanetariumMaker.activeMaking,{id="planetarium_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlanetariumMaker.completeMaking(m) local q=1.0+(PlanetariumMaker.getQualityBonus()/100); if PlanetariumMaker.maker then q=q+(PlanetariumMaker.maker.skill/150) end; q=math.min(2.4,q); PlanetariumMaker.productStock[m.productType]=(PlanetariumMaker.productStock[m.productType] or 0)+m.quantity; PlanetariumMaker.totalProducts=PlanetariumMaker.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlanetariumMaker.maker then PlanetariumMaker.maker.itemsMade=PlanetariumMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlanetariumMaker.maker.skill=math.min(100,PlanetariumMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Planetarij izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"planetarium.completed",{productName=m.productName,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function PlanetariumMaker.update(dt) if not _G.state then return end; PlanetariumMaker.dayTimer=PlanetariumMaker.dayTimer+dt; if PlanetariumMaker.dayTimer>=30 then PlanetariumMaker.dayTimer=0; for i=#PlanetariumMaker.activeMaking,1,-1 do local m=PlanetariumMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlanetariumMaker.completeMaking(m); table.remove(PlanetariumMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlanetariumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlanetariumMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlanetariumMaker.getStats() return {woodStock=PlanetariumMaker.woodStock,brassStock=PlanetariumMaker.brassStock,glassStock=PlanetariumMaker.glassStock,silverStock=PlanetariumMaker.silverStock,goldStock=PlanetariumMaker.goldStock,jewelStock=PlanetariumMaker.jewelStock,pearlStock=PlanetariumMaker.pearlStock,productStock=PlanetariumMaker.productStock,numBuildings=#PlanetariumMaker.buildings,hasMaker=PlanetariumMaker.maker~=nil,makerName=PlanetariumMaker.maker and PlanetariumMaker.maker.name or "—",makerSkill=PlanetariumMaker.maker and PlanetariumMaker.maker.skill or 0,activeMaking=#PlanetariumMaker.activeMaking,totalProducts=PlanetariumMaker.totalProducts} end
return PlanetariumMaker
